//! Port of ICU's `collationfcd.h` / `collationfcd.cpp` (`CollationFCD`): the fast path of
//! the FCD check, one bit per BMP code unit for lccc!=0 and for tccc!=0. The tables are
//! ICU 66's (generated by genuca), transcribed from `collationfcd.cpp`.

/// `hasLccc(c)`: whether the code unit `c` (or `U_SENTINEL`) may have lccc!=0.
#[inline]
pub fn has_lccc(c: i32) -> bool {
    // U+0300 is the first character with lccc!=0.
    if c < 0x300 {
        return false;
    }
    let i = usize::from(LCCC_INDEX[(c >> 5) as usize]);
    i != 0 && (LCCC_BITS[i] & (1u32 << (c & 0x1f))) != 0
}

/// `hasTccc(c)`: whether the code unit `c` may have tccc!=0.
#[inline]
pub fn has_tccc(c: i32) -> bool {
    // U+00C0 is the first character with tccc!=0.
    if c < 0xc0 {
        return false;
    }
    let i = usize::from(TCCC_INDEX[(c >> 5) as usize]);
    i != 0 && (TCCC_BITS[i] & (1u32 << (c & 0x1f))) != 0
}

/// `mayHaveLccc(c)`: like [`has_lccc`] for any code point (supplementary ones by their lead
/// surrogate).
#[inline]
pub fn may_have_lccc(c: i32) -> bool {
    if c < 0x300 {
        return false;
    }
    let c = if c > 0xffff { (c >> 10) + 0xd7c0 } else { c };
    let i = usize::from(LCCC_INDEX[(c >> 5) as usize]);
    i != 0 && (LCCC_BITS[i] & (1u32 << (c & 0x1f))) != 0
}

/// `maybeTibetanCompositeVowel(c)`: U+0F73, U+0F75 or U+0F81 (or a few others).
#[inline]
pub fn maybe_tibetan_composite_vowel(c: i32) -> bool {
    (c & 0x1f_ff01) == 0xf01
}

/// `isFCD16OfTibetanCompositeVowel(fcd16)`: U+0F73 and U+0F75 (0x8182), U+0F81 (0x8184).
#[inline]
pub fn is_fcd16_of_tibetan_composite_vowel(fcd16: u16) -> bool {
    fcd16 == 0x8182 || fcd16 == 0x8184
}

